WIN_EXE.dcdiag = (H, a) => { const { L, d } = H; if (!d.dc) return 'Directory Server Diagnosis\n\nPerforming initial setup:\n   *** Error: ' + d.hostname + ' is not a Directory Server.  Must specify /s:<Directory Server> or /n:<Naming Context> or nothing to use the local machine.\n'; adSync(L); const R = Object.values(L.ad.repl).filter((r) => r.to === d.id); const bad = R.filter((r) => !r.ok); const dnsOk = Object.values(d.nics)[0].dns?.some((x) => L.ad.dcs.some((id) => Object.values(L.devs[id].nics).some((c) => c.ip === x)) || x === '127.0.0.1'); const t = (n, ok, extra = '') => `      Starting test: ${n}\n${extra}         ......................... ${d.hostname} ${ok ? 'passed' : 'failed'} test ${n}\n`; return `\nDirectory Server Diagnosis\n\nPerforming initial setup:\n   Trying to find home server...\n   Home Server = ${d.hostname}\n   * Identified AD Forest. \n   Done gathering initial info.\n\nDoing initial required tests\n   \n   Testing server: Default-First-Site-Name\\${d.hostname}\n${t('Connectivity', true)}\nDoing primary tests\n   \n   Testing server: Default-First-Site-Name\\${d.hostname}\n${t('Advertising', d.svc.NTDS?.status === 'Running')}${t('FrsEvent', true)}${t('DFSREvent', !bad.length, bad.length ? '         There are warning or error events within the last 24 hours after the SYSVOL has been shared.  Failing SYSVOL replication problems may cause Group Policy problems.\n' : '')}${t('SysVolCheck', true)}${t('KccEvent', !bad.length)}${t('KnowsOfRoleHolders', Object.values(L.ad.fsmo).every((id) => L.devs[id] && !L.devs[id].off), Object.values(L.ad.fsmo).some((id) => !L.devs[id] || L.devs[id].off) ? `         Warning: ${L.devs[L.ad.fsmo.pdc]?.hostname} is the PDC Owner, but is not responding to DS RPC Bind.\n` : '')}${t('MachineAccount', true)}${t('NCSecDesc', true)}${t('NetLogons', true)}${t('ObjectsReplicated', true)}${t('Replications', !bad.length, bad.map((r) => `         [Replications Check,${d.hostname}] A recent replication attempt failed:\n            From ${L.devs[r.from].hostname} to ${d.hostname}\n            Naming Context: ${adDnOf(L, '').replace(/^CN=Users,/, '')}\n            The replication generated an error (${r.err.code}):\n            ${r.err.msg}\n            The failure occurred at 2026-10-21 09:${String(10 + r.fails).padStart(2, '0')}:04.\n            ${r.fails} failures have occurred since the last success.\n`).join(''))}${t('RidManager', true)}${t('Services', d.svc.NTDS?.status === 'Running')}${t('SystemLog', !d.events.slice(-30).some((e) => e.level === 'Error' && e.log === 'System'))}${t('VerifyReferences', true)}\n   Running enterprise tests on : ${L.ad.domain}\n${t('DNS', dnsOk, dnsOk ? '' : `         The DNS client of ${d.hostname} does not point to a DNS server that hosts the ${L.ad.domain} zone.\n`).replace(d.hostname + ' ', L.ad.domain + ' ')}`; };
WIN_EXE.repadmin = (H, a) => { const { L, d } = H; if (!L.ad || !d.dc) return { text: 'repadmin running command /replsummary against full DC localhost\n[ERROR] DsBind failed: 1722 (The RPC server is unavailable.)\n', code: 1 }; const op = (a[0] || '').toLowerCase(); adSync(L); const R = L.ad.repl; const nm = (id) => L.devs[id]?.hostname; if (op === '/syncall') { adSync(L); const bad = Object.values(R).filter((r) => !r.ok); return bad.length ? `Syncing all NC's held on ${d.hostname}.\nSyncing partition: ${adDnOf(L, '').replace(/^CN=Users,/, '')}\nSyncAll reported the following errors:\n${bad.map((r) => `Error issuing replication: ${r.err.code} (0x${r.err.code.toString(16)}):\n    "${r.err.msg}"\nFrom: CN=NTDS Settings,CN=${nm(r.from)},CN=Servers,CN=Default-First-Site-Name\nTo  : CN=NTDS Settings,CN=${nm(r.to)},CN=Servers,CN=Default-First-Site-Name`).join('\n\n')}\n` : `Syncing all NC's held on ${d.hostname}.\nSyncing partition: ${adDnOf(L, '').replace(/^CN=Users,/, '')}\nCALLBACK MESSAGE: SyncAll Finished.\nSyncAll terminated with no errors.\n`; } if (op === '/showrepl') return `\nRepadmin: running command /showrepl against full DC localhost\nDefault-First-Site-Name\\${d.hostname}\nDSA Options: IS_GC\nSite Options: (none)\nDSA object GUID: 8c1d2e3f-4a5b-6c7d-8e9f-0a1b2c3d4e5f\n\n==== INBOUND NEIGHBORS ======================================\n\n${adDnOf(L, '').replace(/^CN=Users,/, '')}\n${Object.values(R).filter((r) => r.to === d.id).map((r) => `    Default-First-Site-Name\\${nm(r.from)} via RPC\n        DSA object GUID: 3e4f5a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b\n        ${r.ok ? `Last attempt @ 2026-10-21 09:14:22 was successful.` : `Last attempt @ 2026-10-21 09:14:22 failed, result ${r.err.code} (0x${r.err.code.toString(16)}):\n            ${r.err.msg}\n        ${r.fails} consecutive failure(s).\n        Last success @ 2026-10-20 17:02:11.`}`).join('\n')}\n`; return `Replication Summary Start Time: 2026-10-21 09:15:02\n\nBeginning data collection for replication summary, this may take awhile:\n  ....\n\n\nSource DSA          largest delta    fails/total %%   error\n${L.ad.dcs.map((id) => { const out = Object.values(R).filter((r) => r.from === id); const f = out.filter((r) => !r.ok); return ` ${pad(nm(id), 20)}${pad(f.length ? '16h:12m:03s' : '      05m:12s', 17)}${lpad(f.length, 3)} /  ${lpad(out.length, 2)}  ${lpad(out.length ? Math.round((100 * f.length) / out.length) : 0, 3)}  ${f[0] ? `(${f[0].err.code}) ${f[0].err.msg}` : ''}`; }).join('\n')}\n\n\nDestination DSA     largest delta    fails/total %%   error\n${L.ad.dcs.map((id) => { const inb = Object.values(R).filter((r) => r.to === id); const f = inb.filter((r) => !r.ok); return ` ${pad(nm(id), 20)}${pad(f.length ? '16h:12m:03s' : '      05m:12s', 17)}${lpad(f.length, 3)} /  ${lpad(inb.length, 2)}  ${lpad(inb.length ? Math.round((100 * f.length) / inb.length) : 0, 3)}  ${f[0] ? `(${f[0].err.code}) ${f[0].err.msg}` : ''}`; }).join('\n')}\n`; };
WIN_EXE.netdom = (H, a) => { const { L } = H; if (!L.ad) return { text: 'The specified domain either does not exist or could not be contacted.\n', code: 1 }; if (/query/i.test(a[0] || '') && /fsmo/i.test(a[1] || '')) { const f = L.ad.fsmo, n = (id) => `${L.devs[id]?.hostname}.${L.ad.domain}`; return `Schema master               ${n(f.schema)}\nDomain naming master         ${n(f.naming)}\nPDC                          ${n(f.pdc)}\nRID pool manager             ${n(f.rid)}\nInfrastructure master        ${n(f.infra)}\nThe command completed successfully.\n\n`; } if (/resetpwd/i.test(a[0] || '')) { const c = L.ad.computers[H.d.hostname.toUpperCase()]; if (c) c.pwdOk = true; return 'The machine account password for the local machine has been successfully reset.\n\nThe command completed successfully.\n'; } return 'The syntax of this command is:\n\nNETDOM QUERY FSMO\nNETDOM RESETPWD /server:<dc> /userd:<user> /passwordd:*\n'; };
WIN_EXE.wbadmin = (H, a) => { const { L, d } = H; if (!d.features?.includes('Windows-Server-Backup')) return { text: "'wbadmin' is not recognized as an internal or external command,\noperable program or batch file.\n(Install the Windows-Server-Backup feature first.)\n", code: 1 }; d.wsb ??= { versions: [] }; const op = `${a[0] || ''} ${a[1] || ''}`.toLowerCase(); if (op.startsWith('start systemstatebackup') || op.startsWith('start backup')) { const t = (a.find((x) => /^-backuptarget:/i.test(x)) || '').split(':').slice(1).join(':'); if (!t) return { text: 'ERROR - The backup target was not specified. Use -backupTarget:<volume or UNC path>.\n', code: 1 }; const vol = t.match(/^([A-Z]):?$/i); if (vol && !d.disks.some((k) => k.parts.some((p) => p.letter === vol[1].toUpperCase()))) return { text: `ERROR - The location for backup is not valid: ${t}.\n`, code: 1 }; if (vol && vol[1].toUpperCase() === 'C') return { text: 'ERROR - The location for backup is a critical volume. Choose another volume (a separate disk) for system state backups.\n', code: 1 }; tick(L, 900000); d.wsb.versions.push({ t: L.clock, target: t, kind: op.includes('systemstate') ? 'System State' : 'Volumes' }); return `wbadmin 1.0 - Backup command-line tool\n(C) Copyright Microsoft Corporation. All rights reserved.\n\nStarting to back up the system state [${psDate(psNow(H), 'M/d/yyyy h:mm tt')}]...\nRetrieving volume information...\nThis will back up the system state from volume(s) Local Disk(C:) to ${t}.\nCreating a shadow copy of the volumes specified for backup...\nIdentifying system state files to back up (This might take a few minutes)...\nFound (114582) files.\nThe backup operation successfully completed.\nThe backup of the system state successfully completed [${psDate(psNow(H), 'M/d/yyyy h:mm tt')}].\nLog of files successfully backed up:\nC:\\Windows\\Logs\\WindowsServerBackup\\Backup-21-10-2026_09-30-12.log\n`; } if (op.startsWith('get versions')) return `wbadmin 1.0 - Backup command-line tool\n(C) Copyright Microsoft Corporation. All rights reserved.\n\n${d.wsb.versions.map((v) => `Backup time: ${psDate(winTime(L, d, v.t), 'M/d/yyyy h:mm tt')}\nBackup location: ${v.target}\nVersion identifier: ${psDate(winTime(L, d, v.t), 'MM/dd/yyyy-HH:mm')}\nCan recover: Volume(s), File(s), Application(s), Bare Metal Recovery, System State`).join('\n\n') || 'No backups were found.'}\n`; return 'wbadmin 1.0 - Backup command-line tool\n\nSTART SYSTEMSTATEBACKUP -backupTarget:<volume>\nGET VERSIONS\n'; };
SETTLE_HOOKS.push((L) => { if (L.ad && !L._adSyncing) { L._adSyncing = true; try { adSync(L); } finally { L._adSyncing = false; } } });
